CREATE OR REPLACE FUNCTION kai.c3_a3_verify_gap_link_snapshot_matches_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  source_row kai.gap_log_items;
BEGIN
  SELECT * INTO source_row
    FROM kai.gap_log_items
   WHERE gap_log_item_id = NEW.gap_log_item_id
     AND organization_id = NEW.organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'C3.A3 gap-link snapshot: no kai.gap_log_items row found for gap_log_item_id % in organization %', NEW.gap_log_item_id, NEW.organization_id;
  END IF;

  IF source_row.claim_id IS DISTINCT FROM NEW.claim_id
     OR source_row.evidence_item_id IS DISTINCT FROM NEW.evidence_item_id
     OR source_row.source_version_id IS DISTINCT FROM NEW.source_version_id
     OR source_row.dimension_key IS DISTINCT FROM NEW.dimension_key
     OR source_row.assessment_status IS DISTINCT FROM NEW.assessment_status
  THEN
    RAISE EXCEPTION 'C3.A3 gap-link snapshot does not match kai.gap_log_items row % at insert time', NEW.gap_log_item_id;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION kai.c3_a4_verify_conflict_resolution_link_participation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  conflict_row kai.conflict_groups;
BEGIN
  SELECT * INTO conflict_row
    FROM kai.conflict_groups
   WHERE conflict_group_id = NEW.conflict_group_id
     AND organization_id = NEW.organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'C3.A4 conflict-resolution-link: no kai.conflict_groups row found for conflict_group_id % in organization %', NEW.conflict_group_id, NEW.organization_id;
  END IF;

  IF NEW.claim_id IS DISTINCT FROM conflict_row.lower_claim_id
     AND NEW.claim_id IS DISTINCT FROM conflict_row.higher_claim_id
  THEN
    RAISE EXCEPTION 'C3.A4 conflict-resolution-link: claim_id % does not participate in conflict_group %', NEW.claim_id, NEW.conflict_group_id;
  END IF;

  RETURN NEW;
END;
$function$

