CREATE OR REPLACE FUNCTION kai.c3_a4_verify_source_promotion_link_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  evidence_row kai.evidence_items;
  version_row kai.source_versions;
  decision_row kai.intake_promotion_decisions;
BEGIN
  SELECT * INTO evidence_row
    FROM kai.evidence_items
   WHERE evidence_item_id = NEW.evidence_item_id
     AND organization_id = NEW.organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'C3.A4 source-promotion-link snapshot: no kai.evidence_items row found for evidence_item_id % in organization %', NEW.evidence_item_id, NEW.organization_id;
  END IF;

  IF evidence_row.source_id IS DISTINCT FROM NEW.source_id
     OR evidence_row.source_version_id IS DISTINCT FROM NEW.source_version_id
  THEN
    RAISE EXCEPTION 'C3.A4 source-promotion-link snapshot: evidence_item_id % was not sourced from source_id %/source_version_id %', NEW.evidence_item_id, NEW.source_id, NEW.source_version_id;
  END IF;

  SELECT * INTO version_row
    FROM kai.source_versions
   WHERE source_version_id = NEW.source_version_id
     AND organization_id = NEW.organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'C3.A4 source-promotion-link snapshot: no kai.source_versions row found for source_version_id % in organization %', NEW.source_version_id, NEW.organization_id;
  END IF;

  IF version_row.source_id IS DISTINCT FROM NEW.source_id
     OR version_row.intake_source_candidate_id IS DISTINCT FROM NEW.intake_source_candidate_id
     OR version_row.is_current IS DISTINCT FROM NEW.is_current
  THEN
    RAISE EXCEPTION 'C3.A4 source-promotion-link snapshot does not match kai.source_versions row % at insert time', NEW.source_version_id;
  END IF;

  SELECT * INTO decision_row
    FROM kai.intake_promotion_decisions
   WHERE organization_id = NEW.organization_id
     AND intake_source_candidate_id = NEW.intake_source_candidate_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'C3.A4 source-promotion-link snapshot: no kai.intake_promotion_decisions row found for intake_source_candidate_id % in organization %', NEW.intake_source_candidate_id, NEW.organization_id;
  END IF;

  IF decision_row.intake_promotion_decision_id IS DISTINCT FROM NEW.intake_promotion_decision_id
     OR decision_row.source_id IS DISTINCT FROM NEW.source_id
     OR decision_row.source_version_id IS DISTINCT FROM NEW.source_version_id
     OR decision_row.decision_status IS DISTINCT FROM NEW.decision_status
     OR decision_row.reviewed_source_type IS DISTINCT FROM NEW.reviewed_source_type
  THEN
    RAISE EXCEPTION 'C3.A4 source-promotion-link snapshot does not match kai.intake_promotion_decisions row % at insert time', NEW.intake_promotion_decision_id;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION kai.enforce_gate_a_p0_upload_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  edge text;
  active_count integer;
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.upload_state := COALESCE(NEW.upload_state, 'reserved');
    NEW.upload_state_changed_at := COALESCE(NEW.upload_state_changed_at, COALESCE(NEW.created_at, now()));
    NEW.upload_expires_at := COALESCE(NEW.upload_expires_at, NEW.upload_state_changed_at + interval '24 hours');
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF OLD.organization_id IS DISTINCT FROM NEW.organization_id THEN
      RAISE EXCEPTION 'Gate A P0 tenant identity is immutable';
    END IF;
    IF OLD.intake_file_id IS DISTINCT FROM NEW.intake_file_id THEN
      RAISE EXCEPTION 'Gate A P0 file identity is immutable';
    END IF;
    IF OLD.checksum IS DISTINCT FROM NEW.checksum THEN
      RAISE EXCEPTION 'Gate A P0 declared checksum is immutable';
    END IF;
    IF OLD.hash_algorithm IS DISTINCT FROM NEW.hash_algorithm THEN
      RAISE EXCEPTION 'Gate A P0 hash algorithm is immutable';
    END IF;
    IF OLD.object_version_id IS NOT NULL AND OLD.object_version_id IS DISTINCT FROM NEW.object_version_id THEN
      RAISE EXCEPTION 'Gate A P0 object-version identity is immutable';
    END IF;
    IF OLD.verified_checksum IS NOT NULL AND OLD.verified_checksum IS DISTINCT FROM NEW.verified_checksum THEN
      RAISE EXCEPTION 'Gate A P0 verified checksum is immutable';
    END IF;
    IF OLD.verified_size_bytes IS NOT NULL AND OLD.verified_size_bytes IS DISTINCT FROM NEW.verified_size_bytes THEN
      RAISE EXCEPTION 'Gate A P0 verified size is immutable';
    END IF;
    IF OLD.verified_at IS NOT NULL AND OLD.verified_at IS DISTINCT FROM NEW.verified_at THEN
      RAISE EXCEPTION 'Gate A P0 verification timestamp is immutable';
    END IF;

    IF OLD.upload_state IS DISTINCT FROM NEW.upload_state THEN
      edge := OLD.upload_state || '->' || NEW.upload_state;
      IF edge NOT IN (
        'reserved->upload_started',
        'reserved->policy_blocked',
        'reserved->abandoned',
        'reserved->expired',
        'upload_started->uploaded_unconfirmed',
        'upload_started->policy_blocked',
        'upload_started->abandoned',
        'upload_started->expired',
        'uploaded_unconfirmed->confirmed',
        'uploaded_unconfirmed->policy_blocked',
        'uploaded_unconfirmed->abandoned',
        'uploaded_unconfirmed->expired',
        'confirmed->policy_blocked'
      ) THEN
        RAISE EXCEPTION 'Gate A P0 lifecycle transition denied';
      END IF;

      IF OLD.upload_state IN ('reserved', 'upload_started', 'uploaded_unconfirmed') THEN
        IF NEW.upload_state = 'expired' AND NEW.upload_state_changed_at < OLD.upload_expires_at THEN
          RAISE EXCEPTION 'Gate A P0 cannot expire before upload_expires_at';
        END IF;
        IF NEW.upload_state <> 'expired' AND NEW.upload_state_changed_at >= OLD.upload_expires_at THEN
          RAISE EXCEPTION 'Gate A P0 lifecycle transition denied after expiry';
        END IF;
      END IF;
    END IF;
  END IF;

  IF NEW.upload_state IN ('reserved', 'upload_started', 'uploaded_unconfirmed') THEN
    SELECT count(*)
      INTO active_count
      FROM kai.intake_files f
     WHERE f.organization_id = NEW.organization_id
       AND f.intake_batch_id = NEW.intake_batch_id
       AND f.upload_state IN ('reserved', 'upload_started', 'uploaded_unconfirmed')
       AND (TG_OP = 'INSERT' OR f.intake_file_id <> NEW.intake_file_id);
    IF active_count >= 25 THEN
      RAISE EXCEPTION 'Gate A P0 active upload limit exceeded';
    END IF;
  END IF;

  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION kai.enforce_gate_c1_gcs_generation_binding()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF OLD.gcs_generation IS NOT NULL AND OLD.gcs_generation IS DISTINCT FROM NEW.gcs_generation THEN
      RAISE EXCEPTION 'Gate C-1 gcs_generation binding is immutable once set';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION kai.p3_17_enforce_decision_audience_compatibility()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  candidate_audience text;
BEGIN
  SELECT requested_audience INTO candidate_audience
    FROM kai.export_candidates
   WHERE export_candidate_id = NEW.export_candidate_id
     AND organization_id = NEW.organization_id;

  IF candidate_audience IS NULL THEN
    RAISE EXCEPTION 'P3-17 human-authority-decision-ledger: export_candidate_id % not found for organization %', NEW.export_candidate_id, NEW.organization_id;
  END IF;

  IF NEW.decision_type = 'funder_ready' AND candidate_audience <> 'funder' THEN
    RAISE EXCEPTION 'P3-17 human-authority-decision-ledger: funder_ready may only bind a funder-audience export candidate, bound candidate is %', candidate_audience;
  END IF;

  IF NEW.decision_type = 'public_ready' AND candidate_audience <> 'public' THEN
    RAISE EXCEPTION 'P3-17 human-authority-decision-ledger: public_ready may only bind a public-audience export candidate, bound candidate is %', candidate_audience;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION kai.review_queue_items_p1_06_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION kai.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$function$
